/* Context return and visual-viewport handling. No calculation data is sent. */
(function(root){'use strict';
const KEY='mt.return-context.v1',ttl=86400000;let viewportFrame=null;
const DECIMAL=/^\s*[+-]?(?:\d+(?:[.,]\d*)?|[.,]\d+)(?:e[+-]?\d+)?\s*$/i;
root.MT_PARSE_NUMBER=value=>{if(typeof value!=='string')return Number(value);const text=value.replace(/−/g,'-');return text.trim()&&!DECIMAL.test(text)?NaN:Number(text.replace(',','.'));};
root.MT_PARSE_FLOAT=value=>parseFloat(typeof value==='string'?value.replace(/−/g,'-').replace(',','.'):value);
root.MT_INPUT_KIND=input=>input.dataset?.mtNumeric==='true'?'number':input.type;
function numericFields(scope=document){for(const input of scope.querySelectorAll('input[type=number]')){input.dataset.mtNumeric='true';input.type='text';input.inputMode='decimal';input.setAttribute('role','spinbutton');for(const name of ['min','max'])if(input.hasAttribute(name))input.setAttribute('aria-value'+name,input.getAttribute(name));checkNumber(input);}}
function checkNumber(input){if(input.dataset.mtNumeric!=='true')return;const raw=input.value.trim(),value=root.MT_PARSE_NUMBER(raw),valid=/^[+-]?(?:\d+(?:[.,]\d*)?|[.,]\d+)(?:e[+-]?\d+)?$/i.test(raw.replace(/−/g,'-')),nb=root.MT_I18N?.locale==='nb';let error='';if(raw&&(!valid||!Number.isFinite(value)))error=nb?'Skriv ett tall med komma eller punktum som desimalskilletegn.':'Enter one number with a decimal point or comma.';else if(raw&&input.hasAttribute('min')&&value<Number(input.min))error=(nb?'Minste verdi: ':'Minimum value: ')+input.min;else if(raw&&input.hasAttribute('max')&&value>Number(input.max))error=(nb?'Største verdi: ':'Maximum value: ')+input.max;else if(raw&&input.step&&input.step!=='any'&&Number(input.step)>0){const base=input.hasAttribute('min')?Number(input.min):0,q=(value-base)/Number(input.step);if(Math.abs(q-Math.round(q))>1e-8*Math.max(1,Math.abs(q)))error=(nb?'Bruk trinn på ':'Use increments of ')+input.step;}input.setCustomValidity(error);if(raw&&valid&&Number.isFinite(value))input.setAttribute('aria-valuenow',String(value));else input.removeAttribute('aria-valuenow');}
function viewport(){if(viewportFrame)return;viewportFrame=setTimeout(()=>{viewportFrame=null;const v=root.visualViewport,keyboard=v&&root.innerWidth<=1000&&v.height<root.innerHeight*.74;document.documentElement.toggleAttribute('data-keyboard-open',!!keyboard);if(keyboard&&document.activeElement?.matches('input,textarea'))document.activeElement.scrollIntoView({block:'center',behavior:'instant'});},80);}
function rememberFields(){return [...document.querySelectorAll('main input,main select,main textarea')].filter(n=>!['password','email','file','hidden'].includes(n.type)&&!n.closest('[data-sensitive],#account-view')&&!/password|token|secret|join-code/i.test(n.id+' '+n.name)).slice(0,600).map((n,index)=>({id:n.id,name:n.name,index,value:n.value,checked:n.checked,tag:n.tagName}));}
function restoreFields(saved){if(!Array.isArray(saved))return;for(const field of saved){if(!field.id||field.tag==='INPUT'&&/password|token|secret/i.test(field.id))continue;const n=document.getElementById(field.id);if(!n||n.tagName!==field.tag||['password','email','file','hidden'].includes(n.type))continue;const changed=n.type==='checkbox'||n.type==='radio'?n.checked!==!!field.checked:n.value!==field.value;if(!changed)continue;if(n.type==='checkbox'||n.type==='radio')n.checked=!!field.checked;else if(typeof field.value==='string')n.value=field.value;n.dispatchEvent(new Event('input',{bubbles:true}));n.dispatchEvent(new Event('change',{bubbles:true}));}}
function init(){numericFields();const header=document.querySelector('.next-workspace>header');if(header&&root.ResizeObserver){const resize=new ResizeObserver(()=>document.documentElement.style.setProperty('--workspace-header-height',header.getBoundingClientRect().height+'px'));resize.observe(header);}let numericQueued=false;const observer=new MutationObserver(records=>{if(!records.some(r=>r.addedNodes.length))return;if(numericQueued)return;numericQueued=true;setTimeout(()=>{numericQueued=false;numericFields();},0);});observer.observe(document.body,{childList:true,subtree:true});document.addEventListener('input',e=>checkNumber(e.target),true);document.addEventListener('keydown',e=>{const input=e.target;if(input.dataset?.mtNumeric!=='true'||!['ArrowUp','ArrowDown'].includes(e.key)||input.disabled||input.readOnly)return;e.preventDefault();const step=Number(input.step)>0?Number(input.step):1,min=input.hasAttribute('min')?Number(input.min):-Infinity,max=input.hasAttribute('max')?Number(input.max):Infinity,base=Number.isFinite(min)?min:input.hasAttribute('value')?root.MT_PARSE_NUMBER(input.getAttribute('value')):0,up=e.key==='ArrowUp',raw=input.value.trim(),value=root.MT_PARSE_NUMBER(raw);let next;if(!raw||!Number.isFinite(value)){const start=Math.max(min,Math.min(max,0)),q=(start-base)/step;next=base+(up?Math.ceil(q-1e-10):Math.floor(q+1e-10))*step;}else{const q=(value-base)/step;next=base+(up?Math.floor(q+1e-10)+1:Math.ceil(q-1e-10)-1)*step;}if(next<min)next=base+Math.ceil((min-base)/step-1e-10)*step;if(next>max)next=base+Math.floor((max-base)/step+1e-10)*step;next=Number(next.toPrecision(14));if(!Number.isFinite(next)||next<min||next>max)return;input.value=root.MT_I18N?.locale==='nb'?String(next).replace('.',','):String(next);input.dispatchEvent(new Event('input',{bubbles:true}));input.dispatchEvent(new Event('change',{bubbles:true}));});root.visualViewport?.addEventListener('resize',viewport);root.addEventListener('resize',viewport);document.addEventListener('focusin',e=>{if(e.target.matches('input,textarea,select'))setTimeout(viewport,100);});
 document.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(!a||a.hasAttribute('download')||a.target==='_blank'||a.dataset.returnContext)return;const next=new URL(a.href,location.href);if(next.origin!==location.origin||!/(?:interactive|model-lab|advanced-lab|examples|explorers|labs|cargo|mollier)(?:\.html)?$/.test(next.pathname))return;try{sessionStorage.setItem(KEY,JSON.stringify({version:1,at:Date.now(),from:location.pathname+location.search+location.hash,to:next.pathname+next.search+next.hash,y:root.scrollY,fields:rememberFields()}));}catch{}});
 let saved;try{saved=JSON.parse(sessionStorage.getItem(KEY)||'null');}catch{}if(saved?.version===1&&Date.now()-saved.at<ttl&&typeof saved.from==='string'&&saved.from.startsWith('/')&&!saved.from.startsWith('//')){const here=location.pathname+location.search+location.hash;if(here===saved.to){const nav=document.querySelector('.workspace-toolbar,.student-nav,header nav');if(nav&&!document.getElementById('mt-context-return')){const a=document.createElement('a');a.id='mt-context-return';a.dataset.returnContext='true';a.href=saved.from;a.textContent='Back to where you came from';a.addEventListener('click',()=>{try{sessionStorage.setItem(KEY,JSON.stringify({...saved,returning:true}));}catch{}});nav.append(a);}}else if(saved.returning&&here===saved.from){let tries=0;const restore=()=>{if((document.getElementById('workspace-view')?.getAttribute('aria-busy')==='true'||!document.querySelector('main input,main select,main textarea'))&&++tries<40){setTimeout(restore,50);return;}restoreFields(saved.fields);requestAnimationFrame(()=>root.scrollTo({top:Math.max(0,Number(saved.y)||0),behavior:'instant'}));};setTimeout(restore,0);try{sessionStorage.removeItem(KEY);}catch{}}}
 viewport();}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();root.addEventListener('pagehide',()=>{if(viewportFrame)clearTimeout(viewportFrame);});
})(window);
